// Extract parameters from input
const intent = $input.item.json.intent;
const timeRange = $input.item.json.time_range || 'last_30d';
const filters = $input.item.json.filters || {};

// Map time ranges to actual dates
const now = new Date();
const timeRangeMap = {
  'today': () => {
    const start = new Date(now);
    start.setHours(0, 0, 0, 0);
    return start;
  },
  'yesterday': () => {
    const start = new Date(now);
    start.setDate(start.getDate() - 1);
    start.setHours(0, 0, 0, 0);
    return start;
  },
  'this_week': () => {
    const start = new Date(now);
    start.setDate(start.getDate() - start.getDay());
    start.setHours(0, 0, 0, 0);
    return start;
  },
  'this_month': () => {
    const start = new Date(now.getFullYear(), now.getMonth(), 1);
    return start;
  },
  'last_7d': () => {
    const start = new Date(now);
    start.setDate(start.getDate() - 7);
    return start;
  },
  'last_30d': () => {
    const start = new Date(now);
    start.setDate(start.getDate() - 30);
    return start;
  },
  'last_90d': () => {
    const start = new Date(now);
    start.setDate(start.getDate() - 90);
    return start;
  }
};

const startDate = timeRangeMap[timeRange] ? timeRangeMap[timeRange]() : timeRangeMap['last_30d']();

// Build Gorgias query parameters
const params = {
  created_datetime: {
    $gte: startDate.toISOString()
  }
};

// Add filters if provided
if (filters.status && filters.status.length > 0) {
  params.status = { $in: filters.status };
}

if (filters.assignee_id) {
  params.assignee_user_id = filters.assignee_id;
}

if (filters.tags && filters.tags.length > 0) {
  params.tags = { $in: filters.tags };
}

return {
  json: {
    intent,
    timeRange,
    startDate: startDate.toISOString(),
    endDate: now.toISOString(),
    queryParams: JSON.stringify(params),
    filters
  }
};

// Get tickets data
const ticketsData = $('Fetch Tickets from Gorgias').first().json;
const tickets = ticketsData.data || [];

// Get team data from n8n Data Table
const teamData = $('Fetch Team from Data Table').all().map(item => item.json);

// Get query parameters for context
const queryParams = $('Build Query Parameters').first().json;

// Initialize analytics object
const analytics = {
  totalTickets: tickets.length,
  timeRange: queryParams.timeRange,
  startDate: queryParams.startDate,
  endDate: queryParams.endDate,
  tickets: tickets
};

// Calculate resolution times for closed tickets
const closedTickets = tickets.filter(t => t.status === 'closed');
if (closedTickets.length > 0) {
  const resolutionTimes = closedTickets.map(t => {
    const created = new Date(t.created_datetime);
    const closed = new Date(t.closed_datetime);
    return (closed - created) / (1000 * 60); // minutes
  }).filter(t => t > 0).sort((a, b) => a - b);

  analytics.resolutionTime = {
    count: resolutionTimes.length,
    avg: Math.round(resolutionTimes.reduce((a, b) => a + b, 0) / resolutionTimes.length),
    p50: Math.round(resolutionTimes[Math.floor(resolutionTimes.length * 0.5)]),
    p90: Math.round(resolutionTimes[Math.floor(resolutionTimes.length * 0.9)]),
    min: Math.round(resolutionTimes[0]),
    max: Math.round(resolutionTimes[resolutionTimes.length - 1])
  };
}

// Extract recurring questions (group by subject similarity)
const subjectGroups = {};
tickets.forEach(t => {
  if (t.subject) {
    const key = t.subject.substring(0, 50).toLowerCase().trim();
    if (!subjectGroups[key]) {
      subjectGroups[key] = {
        subject: t.subject,
        count: 0,
        ids: []
      };
    }
    subjectGroups[key].count++;
    subjectGroups[key].ids.push(t.id);
  }
});

analytics.recurringQuestions = Object.values(subjectGroups)
  .filter(g => g.count > 1)
  .sort((a, b) => b.count - a.count)
  .slice(0, 10)
  .map(g => ({
    question: g.subject,
    count: g.count,
    ids: g.ids.slice(0, 10)
  }));

// Tag distribution
const tagCounts = {};
tickets.forEach(t => {
  if (t.tags && Array.isArray(t.tags)) {
    t.tags.forEach(tag => {
      tagCounts[tag.name] = (tagCounts[tag.name] || 0) + 1;
    });
  }
});

analytics.topTags = Object.entries(tagCounts)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 10)
  .map(([tag, count]) => ({ tag, count }));

// Assignee workload with team context
const assigneeCounts = {};
tickets.forEach(t => {
  if (t.assignee_user) {
    const key = t.assignee_user.email;
    if (!assigneeCounts[key]) {
      assigneeCounts[key] = {
        email: key,
        name: t.assignee_user.firstname || key,
        count: 0
      };
    }
    assigneeCounts[key].count++;
  } else {
    if (!assigneeCounts['unassigned']) {
      assigneeCounts['unassigned'] = {
        email: 'unassigned',
        name: 'Unassigned',
        count: 0
      };
    }
    assigneeCounts['unassigned'].count++;
  }
});

// Enhanced assignee analysis with team data
analytics.topAssignees = Object.values(assigneeCounts)
  .map(agent => {
    const teamMember = teamData.find(tm => tm.gorgias_email === agent.email);
    return {
      ...agent,
      role: teamMember?.Role || 'unknown',
      slackId: teamMember?.Slack_Id,
      slackName: teamMember?.Slack_Name,
      percentOfTotal: Math.round((agent.count / tickets.length) * 100)
    };
  })
  .sort((a, b) => b.count - a.count)
  .slice(0, 10);

// Team context
const activeAgentEmails = [...new Set(tickets
  .filter(t => t.assignee_user)
  .map(t => t.assignee_user.email))];

analytics.teamContext = {
  totalAgents: teamData.length,
  activeAgents: activeAgentEmails.length,
  inactiveAgents: teamData.filter(tm => !activeAgentEmails.includes(tm.gorgias_email)),
  admins: teamData.filter(a => a.Role === 'ADMIN').length,
  basic: teamData.filter(a => a.Role === 'BASIC').length,
  avgTicketsPerAgent: tickets.length > 0 ? Math.round(tickets.length / activeAgentEmails.length) : 0
};

// Status distribution
const statusCounts = {};
tickets.forEach(t => {
  statusCounts[t.status] = (statusCounts[t.status] || 0) + 1;
});

analytics.statusDistribution = statusCounts;

// Priority distribution
const priorityCounts = {};
tickets.forEach(t => {
  const priority = t.priority || 'normal';
  priorityCounts[priority] = (priorityCounts[priority] || 0) + 1;
});

analytics.priorityDistribution = priorityCounts;

// Channel distribution
const channelCounts = {};
tickets.forEach(t => {
  channelCounts[t.channel] = (channelCounts[t.channel] || 0) + 1;
});

analytics.channelDistribution = channelCounts;

return { json: analytics };

// Extract output from Tenex response
const tenexResponse = $input.first().json;

return {
  json: {
    output: tenexResponse.output,
    source: 'tenex',
    phase: tenexResponse.phase,
    timestamp: tenexResponse.timestamp
  }
};

// Extract output from Fallback AI response
const aiResponse = $input.first().json;

return {
  json: {
    output: aiResponse.output,
    source: 'fallback_ai',
    timestamp: new Date().toISOString()
  }
};

// Format the final output for Router
const insightsData = $input.first().json;
const analyticsData = $('Calculate Analytics').first().json;

return {
  json: {
    success: true,
    workflow: 'SW3',
    operation: 'analytics_insights',
    insights: insightsData.output,
    source: insightsData.source || 'unknown',
    rawData: {
      totalTickets: analyticsData.totalTickets,
      timeRange: analyticsData.timeRange,
      resolutionTime: analyticsData.resolutionTime,
      topTags: analyticsData.topTags?.slice(0, 5),
      topAssignees: analyticsData.topAssignees?.slice(0, 5),
      teamContext: analyticsData.teamContext,
      statusDistribution: analyticsData.statusDistribution,
      channelDistribution: analyticsData.channelDistribution
    },
    timestamp: new Date().toISOString()
  }
};

return {
  json: {
    success: false,
    workflow: 'SW3',
    error: 'Invalid input parameters',
    message: 'Missing required field: intent',
    timestamp: new Date().toISOString()
  }
};

const error = $input.first().json.error || {};

return {
  json: {
    success: false,
    workflow: 'SW3',
    error: 'Failed to fetch or process analytics',
    details: error.message || JSON.stringify(error),
    timestamp: new Date().toISOString()
  }
};
